-- Query: SituatieDebitori
-- Type: Select

SELECT X.IDZ, X.IDP, X.IDL, [lunat] & "/" & [anul] AS Luna, X.Grupa, X.Nume, X.CNP, X.ZileLuna, X.ZilePrezenta, X.ZileAbsenta, X.SID, X.SIC, X.ValoareContract, X.ValoareMancare, X.ReducereFrate, X.Avans, X.Valoare, X.Platita, X.Detalii, X.TIP, CDbl(IIf([SID]-[sic]+[VALOARE]-[platita]>0,[SID]-[sic]+[VALOARE]-[platita],0)) AS SFD, CDbl(IIf([SID]-[sic]+[VALOARE]-[platita]<0,[SID]-[sic]+[VALOARE]-[platita],0)) AS SFC
FROM (SELECT Prezenta.IDZ, Prezenta.IDP, Prezenta.IDL, LunaD.LunaT, LunaD.Anul, Grupe.Grupa, Platitori.Nume, Platitori.CNP, Prezenta.ZileLuna, Prezenta.ZilePrezenta, Prezenta.ZileAbsenta, CDbl(Nz(IIf([SI]<0,0,[si]),0)) AS SID, Abs(CDbl(Nz(IIf([SI]>0,0,[si])))) AS SIC, Prezenta.ValoareContract, Prezenta.ValoareMancare, Prezenta.ReducereFrate, Prezenta.Avans, Prezenta.ValoareTotala AS Valoare, Sum(CDbl(Nz([Plata],0))) AS Platita, "" AS Detalii, First(Plati.TIP) AS TIP FROM ((Grupe INNER JOIN (Platitori LEFT JOIN SoldInitial ON Platitori.IDP = SoldInitial.IDP) ON Grupe.IDG = Platitori.IDG) INNER JOIN (LunaD INNER JOIN Prezenta ON LunaD.IDL = Prezenta.IDL) ON Platitori.IDP = Prezenta.IDP) LEFT JOIN Plati ON Prezenta.IDZ = Plati.IDZ WHERE (((dhLastDayInMonth(CDate("01/" & [luna] & "/" & [anul])))=dhLastDayInMonth(CDate("01/" & [forms]![prezenta]![luni]![luna] & "/" & [forms]![prezenta]![luni]![anul])))) GROUP BY Prezenta.IDZ, Prezenta.IDP, Prezenta.IDL, LunaD.LunaT, LunaD.Anul, Grupe.Grupa, Platitori.Nume, Platitori.CNP, Prezenta.ZileLuna, Prezenta.ZilePrezenta, Prezenta.ZileAbsenta, CDbl(Nz(IIf([SI]<0,0,[si]),0)), Abs(CDbl(Nz(IIf([SI]>0,0,[si])))), Prezenta.ValoareContract, Prezenta.ValoareMancare, Prezenta.ReducereFrate, Prezenta.Avans, Prezenta.ValoareTotala, "")  AS X
GROUP BY X.IDZ, X.IDP, X.IDL, [lunat] & "/" & [anul], X.Grupa, X.Nume, X.CNP, X.ZileLuna, X.ZilePrezenta, X.ZileAbsenta, X.SID, X.SIC, X.ValoareContract, X.ValoareMancare, X.ReducereFrate, X.Avans, X.Valoare, X.Platita, X.Detalii, X.TIP, CDbl(IIf([SID]-[sic]+[VALOARE]-[platita]>0,[SID]-[sic]+[VALOARE]-[platita],0)), CDbl(IIf([SID]-[sic]+[VALOARE]-[platita]<0,[SID]-[sic]+[VALOARE]-[platita],0));
